CREATE TABLE store_delivery_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,store_id uuid NOT NULL,shipment_id uuid NOT NULL REFERENCES shipments(id) ON DELETE RESTRICT,status text NOT NULL CHECK(status IN('received','received_with_discrepancy')),notes text,received_by uuid NOT NULL REFERENCES users(id),received_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,shipment_id),FOREIGN KEY(company_id,store_id) REFERENCES requesting_stores(company_id,id),UNIQUE(company_id,id));
CREATE TABLE store_delivery_receipt_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,receipt_id uuid NOT NULL,order_line_id uuid NOT NULL REFERENCES sales_order_lines(id) ON DELETE RESTRICT,expected_quantity numeric(18,6) NOT NULL CHECK(expected_quantity>=0),accepted_quantity numeric(18,6) NOT NULL CHECK(accepted_quantity>=0),short_quantity numeric(18,6) NOT NULL CHECK(short_quantity>=0),damaged_quantity numeric(18,6) NOT NULL CHECK(damaged_quantity>=0),FOREIGN KEY(company_id,receipt_id) REFERENCES store_delivery_receipts(company_id,id),CHECK(accepted_quantity+short_quantity+damaged_quantity=expected_quantity),UNIQUE(receipt_id,order_line_id));
ALTER TABLE store_delivery_receipts ENABLE ROW LEVEL SECURITY;ALTER TABLE store_delivery_receipts FORCE ROW LEVEL SECURITY;ALTER TABLE store_delivery_receipt_lines ENABLE ROW LEVEL SECURITY;ALTER TABLE store_delivery_receipt_lines FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_store_delivery_receipts ON store_delivery_receipts USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);CREATE POLICY tenant_store_delivery_receipt_lines ON store_delivery_receipt_lines USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);
GRANT SELECT,INSERT,UPDATE,DELETE ON store_delivery_receipts,store_delivery_receipt_lines TO stockflow_app;
